points.code:
if (get TextBox_Email.Text = "admin@megaminds.com") and (get PasswordTextBox1.Text = "12345")
then call open another screen (screenName = "HomeScreen")
else set Label_Error.Text to "البيانات غير صحيحة!"

// حفظ البيانات
call TinyDB1.StoreValue (tag = "username", valueToStore = TextBox_Name.Text)
// استرجاع البيانات
set Label_Welcome.Text to call TinyDB1.GetValue (tag = "username", valueIfTagNotThere = "مستخدم جديد")

set global pcChoice to call pick a random item (list = create empty list ["حجر", "ورق", "مقص"])
if (get global userChoice = get global pcChoice)
then set Label_Status.Text to "تعادل!"
else if (get global userChoice = "حجر" and get global pcChoice = "مقص")
then set Label_Status.Text to "أنت الفائز! 🎉"

// الانتقال إلى شاشة العيادة مع إرسال اسم المريض
call open another screen with start value (screenName = "ClinicScreen", startValue = get studentInfo.name)
// استلام الاسم في شاشة العيادة
set Label_PatientName.Text to get start value
